<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/JalaliDate.php';require_once __DIR__.'/OrgAccess.php';
final class ManagementMeetingsRepository
{
 const MEETING_STATUSES=['draft'=>'پیش‌نویس','registered'=>'ثبت‌شده','finalized'=>'نهایی‌شده','archived'=>'بایگانی‌شده'];
 const DECISION_STATUSES=['not_started'=>'شروع‌نشده','assigned'=>'ارجاع‌شده','in_progress'=>'در حال پیگیری','waiting'=>'در انتظار پاسخ','needs_revision'=>'نیازمند اصلاح','done'=>'انجام‌شده','verified'=>'تأیید نهایی','overdue'=>'عقب‌افتاده','cancelled'=>'لغوشده'];
 const PRIORITIES=['low'=>'کم','normal'=>'عادی','high'=>'مهم','urgent'=>'فوری'];
 const DECISION_TYPES=['decision'=>'مصوبه','action'=>'اقدام اجرایی','internal_rule'=>'قانون داخلی','followup'=>'پیگیری','reminder'=>'یادآوری','amendment'=>'اصلاحیه'];
 public static function canCreateMeeting(?array $u=null):bool{$u=$u?:Auth::user();return $u&& (OrgAccess::isAdmin($u)||($u['role']??'')==='manager'||Auth::can('management_meetings','create'));}
 public static function canManageRules(?array $u=null):bool{$u=$u?:Auth::user();return $u&&OrgAccess::isAdmin($u);}
 public static function canEditDecision(array $d,?array $u=null):bool{$u=$u?:Auth::user();return $u&&(OrgAccess::isAdmin($u)||in_array((int)$d['created_by'],OrgAccess::accessibleUserIds($u),true));}
 public static function canFollowupDecision(array $d,?array $u=null):bool{$u=$u?:Auth::user();if(!$u)return false;if(OrgAccess::isAdmin($u)||(int)$d['responsible_user_id']===(int)$u['id']||(int)$d['supervisor_user_id']===(int)$u['id'])return true;return ($u['role']??'')==='manager'&&OrgAccess::canAccessUser($u,(int)$d['responsible_user_id']);}
 public static function canVerifyDecision(array $d,?array $u=null):bool{$u=$u?:Auth::user();return $u&&(OrgAccess::isAdmin($u)||(int)$d['supervisor_user_id']===(int)$u['id']);}
 public static function menuAllowed():bool{$u=Auth::user();if(!$u)return false;if(OrgAccess::isAdmin($u)||($u['role']??'')==='manager'||Auth::can('management_meetings')||Auth::can('management_decisions')||Auth::can('management_rules'))return true;return (bool)Database::fetch('SELECT d.id FROM management_decisions d JOIN management_meetings m ON m.id=d.meeting_id WHERE d.responsible_user_id=? OR d.supervisor_user_id=? OR m.organizer_user_id=? OR m.secretary_user_id=? LIMIT 1',[(int)$u['id'],(int)$u['id'],(int)$u['id'],(int)$u['id']]);}
 public static function getMeetings(array $f=[],?array $u=null):array{$u=$u?:Auth::user();if(!$u)return [];[$scope,$p]=self::meetingScope($u,'m');$w=[$scope];if(($f['id']??0)>0){$w[]='m.id=?';$p[]=(int)$f['id'];}foreach(['meeting_type','status','meeting_date'] as $k)if(trim((string)($f[$k]??''))!==''){$w[]="m.{$k}=?";$p[]=self::text($f[$k],50);}foreach(['organizer_user_id','secretary_user_id'] as $k)if((int)($f[$k]??0)>0){$w[]="m.{$k}=?";$p[]=(int)$f[$k];}return Database::fetchAll('SELECT m.*,o.name organizer_name,s.name secretary_name,c.name creator_name,(SELECT COUNT(*) FROM management_decisions d WHERE d.meeting_id=m.id) decision_count FROM management_meetings m LEFT JOIN users o ON o.id=m.organizer_user_id LEFT JOIN users s ON s.id=m.secretary_user_id LEFT JOIN users c ON c.id=m.created_by WHERE '.implode(' AND ',$w).' ORDER BY m.meeting_date DESC,m.id DESC',$p);}
 public static function getMeetingById(int $id,?array $u=null):?array{$r=self::getMeetings(['id'=>$id],$u);if(!$r)return null;$m=$r[0];$m['attendees']=self::jsonIds($m['attendees_json']);$m['absent_users']=self::jsonIds($m['absent_users_json']);$m['attachments']=self::json($m['attachments_json']);return $m;}
 public static function createMeeting(array $d,int $by):int{$u=Auth::user();if(!$u||$by!==(int)$u['id']||!self::canCreateMeeting($u))throw new DomainException('شما دسترسی ثبت صورتجلسه را ندارید.');$v=self::meetingData($d);Database::execute('INSERT INTO management_meetings(title,meeting_type,meeting_date,start_time,end_time,location,organizer_user_id,secretary_user_id,attendees_json,absent_users_json,agenda,meeting_summary,status,attachments_json,created_by,updated_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,"draft",?,?,?,NOW(),NOW())',[$v['title'],$v['meeting_type'],$v['meeting_date'],$v['start_time'],$v['end_time'],$v['location'],$v['organizer_user_id'],$v['secretary_user_id'],self::encode($v['attendees']),self::encode($v['absent_users']),$v['agenda'],$v['meeting_summary'],self::encode($v['attachments']),$by,$by]);$id=(int)Database::lastInsertId();Auth::log($by,'meeting_created','management_meetings',$id);return $id;}
 public static function updateMeeting(int $id,array $d,int $by):void{$m=self::requireMeeting($id);self::assertMeetingEditor($m,Auth::user());if($m['status']==='archived')throw new DomainException('صورتجلسه بایگانی‌شده قابل ویرایش نیست.');$v=self::meetingData($d);Database::execute('UPDATE management_meetings SET title=?,meeting_type=?,meeting_date=?,start_time=?,end_time=?,location=?,organizer_user_id=?,secretary_user_id=?,attendees_json=?,absent_users_json=?,agenda=?,meeting_summary=?,attachments_json=?,updated_by=?,updated_at=NOW() WHERE id=?',[$v['title'],$v['meeting_type'],$v['meeting_date'],$v['start_time'],$v['end_time'],$v['location'],$v['organizer_user_id'],$v['secretary_user_id'],self::encode($v['attendees']),self::encode($v['absent_users']),$v['agenda'],$v['meeting_summary'],self::encode($v['attachments']),$by,$id]);Auth::log($by,'meeting_updated','management_meetings',$id);}
 public static function finalizeMeeting(int $id,int $by):void{$m=self::requireMeeting($id);self::assertMeetingEditor($m,Auth::user());if(!in_array($m['status'],['draft','registered'],true))throw new DomainException('این صورتجلسه امکان نهایی‌سازی ندارد.');Database::execute('UPDATE management_meetings SET status="finalized",updated_by=?,updated_at=NOW() WHERE id=?',[$by,$id]);Auth::log($by,'meeting_finalized','management_meetings',$id);}
 public static function archiveMeeting(int $id,int $by):void{$m=self::requireMeeting($id);self::assertMeetingEditor($m,Auth::user());Database::execute('UPDATE management_meetings SET status="archived",updated_by=?,updated_at=NOW() WHERE id=?',[$by,$id]);Auth::log($by,'meeting_archived','management_meetings',$id);}
 public static function getDecisions(array $f=[],?array $u=null):array{$u=$u?:Auth::user();if(!$u)return [];[$scope,$p]=self::decisionScope($u,'d','m');$w=[$scope];if((int)($f['id']??0)>0){$w[]='d.id=?';$p[]=(int)$f['id'];}$map=['status'=>'d.followup_status','priority'=>'d.priority','responsible_user_id'=>'d.responsible_user_id','responsible_unit_id'=>'d.responsible_unit_id','meeting_id'=>'d.meeting_id'];foreach($map as $k=>$c)if(trim((string)($f[$k]??''))!==''){$w[]="$c=?";$p[]=(int)$f[$k]?:self::text($f[$k],50);}if(!empty($f['mine'])){$w[]='d.responsible_user_id=?';$p[]=(int)$u['id'];}if(!empty($f['my_unit'])&&(int)($u['org_unit_id']??0)){$w[]='d.responsible_unit_id=?';$p[]=(int)$u['org_unit_id'];}if(!empty($f['overdue']))$w[]='d.due_date<CURDATE() AND d.followup_status NOT IN("done","verified","cancelled")';foreach(['due_from'=>'d.due_date>=?','due_to'=>'d.due_date<=?','meeting_from'=>'m.meeting_date>=?','meeting_to'=>'m.meeting_date<=?'] as $k=>$x)if(trim((string)($f[$k]??''))!==''){$w[]=$x;$p[]=self::date($f[$k]);}return Database::fetchAll('SELECT d.*,IF(d.due_date<CURDATE() AND d.followup_status NOT IN("done","verified","cancelled"),"overdue",d.followup_status) display_status,m.title meeting_title,m.meeting_date,r.name responsible_name,s.name supervisor_name,ou.title responsible_unit_title,v.name verified_name FROM management_decisions d JOIN management_meetings m ON m.id=d.meeting_id LEFT JOIN users r ON r.id=d.responsible_user_id LEFT JOIN users s ON s.id=d.supervisor_user_id LEFT JOIN users v ON v.id=d.verified_by LEFT JOIN org_units ou ON ou.id=d.responsible_unit_id WHERE '.implode(' AND ',$w).' ORDER BY FIELD(display_status,"overdue","needs_revision","in_progress","assigned","not_started","waiting","done","verified","cancelled"),d.due_date,d.id DESC',$p);}
 public static function getDecisionById(int $id,?array $u=null):?array{$rows=self::getDecisions(['id'=>$id],$u);if(!$rows){$u=$u?:Auth::user();[$s,$p]=self::decisionScope($u,'d','m');array_unshift($p,$id);$row=Database::fetch('SELECT d.*,m.title meeting_title,m.meeting_date,r.name responsible_name,su.name supervisor_name,ou.title responsible_unit_title FROM management_decisions d JOIN management_meetings m ON m.id=d.meeting_id LEFT JOIN users r ON r.id=d.responsible_user_id LEFT JOIN users su ON su.id=d.supervisor_user_id LEFT JOIN org_units ou ON ou.id=d.responsible_unit_id WHERE d.id=? AND '.$s,$p);return $row?:null;}return $rows[0];}
 public static function createDecision(array $d,int $by):int{$m=self::requireMeeting((int)($d['meeting_id']??0));self::assertMeetingEditor($m,Auth::user());$v=self::decisionData($d);$pdo=Database::connection();$pdo->beginTransaction();try{Database::execute('INSERT INTO management_decisions(meeting_id,title,description,decision_type,category,responsible_user_id,responsible_unit_id,supervisor_user_id,priority,due_date,followup_status,progress_percent,latest_followup_note,is_rule,rule_effective_date,rule_expire_date,created_by,updated_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',[$m['id'],$v['title'],$v['description'],$v['decision_type'],$v['category'],$v['responsible_user_id'],$v['responsible_unit_id'],$v['supervisor_user_id'],$v['priority'],$v['due_date'],$v['followup_status'],$v['progress_percent'],$v['latest_followup_note'],$v['is_rule'],$v['rule_effective_date'],$v['rule_expire_date'],$by,$by]);$id=(int)Database::lastInsertId();self::addFollowup($id,null,$v['followup_status'],$v['progress_percent'],$v['latest_followup_note'],null,null,$by,true);$pdo->commit();Auth::log($by,'decision_created','management_decisions',$id);return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public static function updateDecision(int $id,array $d,int $by):void{$old=self::requireDecision($id);self::assertDecisionEditor($old,Auth::user());$v=self::decisionData(array_merge($old,$d));Database::execute('UPDATE management_decisions SET title=?,description=?,decision_type=?,category=?,responsible_user_id=?,responsible_unit_id=?,supervisor_user_id=?,priority=?,due_date=?,is_rule=?,rule_effective_date=?,rule_expire_date=?,updated_by=?,updated_at=NOW() WHERE id=?',[$v['title'],$v['description'],$v['decision_type'],$v['category'],$v['responsible_user_id'],$v['responsible_unit_id'],$v['supervisor_user_id'],$v['priority'],$v['due_date'],$v['is_rule'],$v['rule_effective_date'],$v['rule_expire_date'],$by,$id]);Auth::log($by,'decision_updated','management_decisions',$id);}
 public static function updateDecisionStatus(int $id,string $status,int $progress,string $note,int $by,?string $next=null,?string $attachment=null):void{$d=self::requireDecision($id);self::assertFollowup($d,Auth::user());$status=self::status($status);$progress=max(0,min(100,$progress));if($status==='verified'&&!self::canVerify($d,Auth::user()))throw new DomainException('تأیید نهایی فقط توسط ناظر یا مدیر مجاز است.');if($status==='verified'&&$d['followup_status']!=='done'&&$progress<100)throw new DomainException('امکان تأیید نهایی پیش از تکمیل پیگیری وجود ندارد.');$pdo=Database::connection();$pdo->beginTransaction();try{Database::execute('UPDATE management_decisions SET followup_status=?,progress_percent=?,latest_followup_note=?,closed_at=IF(?="done",NOW(),closed_at),closed_by=IF(?="done",?,closed_by),verified_by=IF(?="verified",?,verified_by),verification_status=IF(?="verified","verified",verification_status),updated_by=?,updated_at=NOW() WHERE id=?',[$status,$progress,self::text($note,5000),$status,$status,$by,$status,$by,$status,$by,$id]);self::addFollowup($id,$d['followup_status'],$status,$progress,$note,$next,$attachment,$by,true);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public static function verifyDecision(int $id,int $by):void{$d=self::requireDecision($id);if(!self::canVerify($d,Auth::user()))throw new DomainException('شما مجاز به تأیید نهایی نیستید.');self::updateDecisionStatus($id,'verified',100,'تأیید نهایی انجام مصوبه',$by);}
 public static function addFollowup(int $id,?string $old,string $new,int $progress,string $note,?string $next,?string $attachment,int $by,bool $trusted=false):void{if(!$trusted){$d=self::requireDecision($id);self::assertFollowup($d,Auth::user());}Database::execute('INSERT INTO management_decision_followups(decision_id,old_status,new_status,progress_percent,followup_note,next_followup_date,attachment_json,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())',[$id,$old,$new,max(0,min(100,$progress)),self::text($note,5000),$next?self::date($next):null,$attachment,$by]);}
 public static function getDecisionFollowups(int $id):array{self::requireDecision($id);return Database::fetchAll('SELECT f.*,u.name creator_name FROM management_decision_followups f LEFT JOIN users u ON u.id=f.created_by WHERE f.decision_id=? ORDER BY f.id DESC',[$id]);}
 public static function convertDecisionToRule(int $id,array $r,int $by):int{$d=self::requireDecision($id);if(!self::canManageRules())throw new DomainException('تبدیل مصوبه به قانون فقط برای مدیر سیستم مجاز است.');$code=self::required($r['rule_code']??'','کد قانون');$code=self::text($code,100);$title=self::required($r['title']??$d['title'],'عنوان قانون');$content=self::required($r['content']??$d['description'],'متن قانون');$effective=self::date($r['effective_date']??$d['rule_effective_date']??date('Y-m-d'));$scope=in_array($r['scope_type']??'company',['company','department','role','sales_line','user'],true)?$r['scope_type']:'company';$version=(int)(Database::fetch('SELECT COALESCE(MAX(version_number),0)+1 n FROM management_rule_versions WHERE rule_code=?',[$code])['n']??1);$pdo=Database::connection();$pdo->beginTransaction();try{if(!empty($r['active']))Database::execute('UPDATE management_rule_versions SET active=0 WHERE rule_code=?',[$code]);Database::execute('INSERT INTO management_rule_versions(decision_id,rule_code,title,content,version_number,effective_date,expire_date,scope_type,scope_value,active,approved_by,approved_at,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,IF(?=1,NOW(),NULL),?,NOW())',[$id,$code,$title,$content,$version,$effective,trim((string)($r['expire_date']??''))?self::date($r['expire_date']):null,$scope,self::text($r['scope_value']??'',190)?:null,!empty($r['active'])?1:0,!empty($r['active'])?$by:null,!empty($r['active'])?1:0,$by]);$rid=(int)Database::lastInsertId();Database::execute('UPDATE management_decisions SET is_rule=1,rule_effective_date=?,rule_expire_date=?,updated_by=?,updated_at=NOW() WHERE id=?',[$effective,trim((string)($r['expire_date']??''))?self::date($r['expire_date']):null,$by,$id]);$pdo->commit();Auth::log($by,'decision_converted_to_rule','management_rules',$rid);return $rid;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public static function getActiveRules(array $f=[],?array $u=null):array{$u=$u?:Auth::user();$w=['1=1'];$p=[];if(!self::canManageRules($u)){[$s,$sp]=self::ruleScope($u);$w[]=$s;$p=array_merge($p,$sp);}if(isset($f['active'])&&$f['active']!==''){$w[]='rv.active=?';$p[]=(int)$f['active'];}foreach(['scope_type','scope_value','rule_code'] as $k)if(trim((string)($f[$k]??''))!==''){$w[]="rv.{$k}=?";$p[]=self::text($f[$k],190);}return Database::fetchAll('SELECT rv.*,d.title decision_title,m.id meeting_id,m.title meeting_title,u.name approved_name FROM management_rule_versions rv JOIN management_decisions d ON d.id=rv.decision_id JOIN management_meetings m ON m.id=d.meeting_id LEFT JOIN users u ON u.id=rv.approved_by WHERE '.implode(' AND ',$w).' ORDER BY rv.active DESC,rv.rule_code,rv.version_number DESC',$p);}
 public static function getRuleVersions(int $decisionId):array{return Database::fetchAll('SELECT rv.*,u.name approved_name FROM management_rule_versions rv LEFT JOIN users u ON u.id=rv.approved_by WHERE rv.decision_id=? ORDER BY rv.version_number DESC',[$decisionId]);}
 public static function archiveRule(int $id,int $by):void{if(!self::canManageRules())throw new DomainException('دسترسی تغییر قانون را ندارید.');Database::execute('UPDATE management_rule_versions SET active=0 WHERE id=?',[$id]);Auth::log($by,'rule_archived','management_rules',$id);}
 public static function meetingStats(?array $u=null):array{$m=self::getMeetings([],$u);$d=self::getDecisions([],$u);$rules=self::getActiveRules(['active'=>1],$u);return ['meetings'=>count($m),'month_meetings'=>count(array_filter($m,fn($x)=>substr($x['meeting_date'],0,7)===date('Y-m'))),'open'=>count(array_filter($d,fn($x)=>!in_array($x['display_status'],['done','verified','cancelled'],true))),'overdue'=>count(array_filter($d,fn($x)=>$x['display_status']==='overdue')),'done'=>count(array_filter($d,fn($x)=>in_array($x['followup_status'],['done','verified'],true))),'rules'=>count($rules)];}
 public static function decisionStats(array $rows):array{return ['total'=>count($rows),'open'=>count(array_filter($rows,fn($x)=>!in_array($x['display_status'],['done','verified','cancelled'],true))),'overdue'=>count(array_filter($rows,fn($x)=>$x['display_status']==='overdue')),'done'=>count(array_filter($rows,fn($x)=>$x['followup_status']==='done')),'verify'=>count(array_filter($rows,fn($x)=>$x['followup_status']==='done'&&$x['verification_status']!=='verified')),'urgent'=>count(array_filter($rows,fn($x)=>$x['priority']==='urgent'))];}
 public static function managementAnalytics(array $rows,?array $u=null):array{$open=[];$overdue=[];$meetings=[];$durations=[];$monthTotal=0;$monthDone=0;foreach($rows as $r){$meetings[$r['meeting_title']]=($meetings[$r['meeting_title']]??0)+1;if(!in_array($r['display_status'],['done','verified','cancelled'],true))$open[$r['responsible_name']??'بدون مسئول']=($open[$r['responsible_name']??'بدون مسئول']??0)+1;if($r['display_status']==='overdue')$overdue[$r['responsible_unit_title']??'بدون واحد']=($overdue[$r['responsible_unit_title']??'بدون واحد']??0)+1;if($r['closed_at'])$durations[]=max(0,(strtotime($r['closed_at'])-strtotime($r['created_at']))/86400);if(substr($r['created_at'],0,7)===date('Y-m')){$monthTotal++;if(in_array($r['followup_status'],['done','verified'],true))$monthDone++;}}arsort($open);arsort($overdue);arsort($meetings);$rules=self::getActiveRules([], $u?:Auth::user());return ['open_by_responsible'=>$open,'overdue_by_unit'=>$overdue,'decisions_by_meeting'=>$meetings,'average_days'=>$durations?round(array_sum($durations)/count($durations),1):0,'month_percent'=>$monthTotal?round($monthDone*100/$monthTotal):0,'active_rules'=>count(array_filter($rules,fn($x)=>(int)$x['active']&&(!$x['expire_date']||$x['expire_date']>=date('Y-m-d')))),'expired_rules'=>count(array_filter($rules,fn($x)=>$x['expire_date']&&$x['expire_date']<date('Y-m-d')))];}
 public static function users():array{$u=Auth::user();if(!$u)return [];$ids=OrgAccess::accessibleUserIds($u);if(!$ids)return [];$ph=implode(',',array_fill(0,count($ids),'?'));return Database::fetchAll("SELECT id,name,department,org_unit_id,role FROM users WHERE status='active' AND id IN ({$ph}) ORDER BY name",$ids);}public static function units():array{$u=Auth::user();if(!$u)return [];if(OrgAccess::isAdmin($u))return Database::fetchAll('SELECT id,title FROM org_units WHERE active=1 ORDER BY title');if((int)($u['org_unit_id']??0))return Database::fetchAll('SELECT id,title FROM org_units WHERE active=1 AND id=?',[(int)$u['org_unit_id']]);return [];}
 private static function meetingScope(array $u,string $a):array{if(OrgAccess::isAdmin($u))return ['1=1',[]];$ids=OrgAccess::accessibleUserIds($u);$ph=implode(',',array_fill(0,count($ids),'?'));$uid=(int)$u['id'];$sql="({$a}.created_by IN ({$ph}) OR {$a}.organizer_user_id IN ({$ph}) OR {$a}.secretary_user_id IN ({$ph}) OR JSON_CONTAINS(COALESCE({$a}.attendees_json,'[]'),?, '$') OR EXISTS(SELECT 1 FROM management_decisions sd WHERE sd.meeting_id={$a}.id AND (sd.responsible_user_id IN ({$ph}) OR sd.supervisor_user_id IN ({$ph})";$p=array_merge($ids,$ids,$ids,[(string)$uid],$ids,$ids);if((int)($u['org_unit_id']??0)){$sql.=' OR sd.responsible_unit_id=?';$p[]=(int)$u['org_unit_id'];}$sql.=')))';return [$sql,$p];}
 private static function decisionScope(array $u,string $d,string $m):array{if(OrgAccess::isAdmin($u))return ['1=1',[]];$ids=OrgAccess::accessibleUserIds($u);$ph=implode(',',array_fill(0,count($ids),'?'));$sql="({$d}.responsible_user_id IN ({$ph}) OR {$d}.supervisor_user_id IN ({$ph}) OR {$m}.organizer_user_id IN ({$ph}) OR {$m}.secretary_user_id IN ({$ph})";$p=array_merge($ids,$ids,$ids,$ids);if((int)($u['org_unit_id']??0)){$sql.=" OR {$d}.responsible_unit_id=?";$p[]=(int)$u['org_unit_id'];}$sql.=')';return [$sql,$p];}
 private static function ruleScope(array $u):array{$parts=['rv.scope_type="company"'];$p=[];if((int)($u['org_unit_id']??0)){$parts[]='(rv.scope_type="department" AND rv.scope_value=?)';$p[]=(string)$u['org_unit_id'];}if((int)($u['org_role_id']??0)){$parts[]='(rv.scope_type="role" AND rv.scope_value=?)';$p[]=(string)$u['org_role_id'];}if(trim((string)($u['sales_line']??''))!==''){$parts[]='(rv.scope_type="sales_line" AND rv.scope_value=?)';$p[]=$u['sales_line'];}$parts[]='(rv.scope_type="user" AND rv.scope_value=?)';$p[]=(string)$u['id'];return ['('.implode(' OR ',$parts).')',$p];}
 private static function requireMeeting(int $id):array{$m=self::getMeetingById($id);if(!$m)throw new DomainException('صورتجلسه در دسترس نیست.');return $m;}private static function requireDecision(int $id):array{$d=self::getDecisionById($id);if(!$d)throw new DomainException('مصوبه در دسترس نیست.');return $d;}
 private static function assertMeetingEditor(array $m,?array $u):void{if(!$u)throw new DomainException('دسترسی غیرمجاز است.');if(OrgAccess::isAdmin($u))return;$uid=(int)$u['id'];if(($u['role']??'')==='manager'&&in_array((int)$m['created_by'],OrgAccess::accessibleUserIds($u),true))return;if(in_array($uid,[(int)$m['created_by'],(int)$m['organizer_user_id'],(int)$m['secretary_user_id']],true))return;throw new DomainException('شما مجاز به ویرایش این صورتجلسه نیستید.');}
 private static function assertDecisionEditor(array $d,?array $u):void{if(self::canEditDecision($d,$u))return;throw new DomainException('شما مجاز به ویرایش این مصوبه نیستید.');}
 private static function assertFollowup(array $d,?array $u):void{if(self::canFollowupDecision($d,$u))return;throw new DomainException('فقط مسئول یا ناظر مجاز به ثبت پیگیری است.');}
 private static function canVerify(array $d,?array $u):bool{return self::canVerifyDecision($d,$u);}
 private static function meetingData(array $d):array{$title=self::required($d['title']??'','عنوان جلسه');$date=self::date($d['meeting_date']??'');$start=self::time($d['start_time']??'');$end=self::time($d['end_time']??'');if($start&&$end&&$end<$start)throw new InvalidArgumentException('ساعت پایان نمی‌تواند قبل از شروع باشد.');$attendees=array_values(array_unique(array_filter(array_map('intval',(array)($d['attendees']??[])))));$absent=array_values(array_unique(array_filter(array_map('intval',(array)($d['absent_users']??[])))));$organizer=(int)($d['organizer_user_id']??0)?:null;$secretary=(int)($d['secretary_user_id']??0)?:null;$actor=Auth::user();$targets=array_values(array_filter(array_merge($attendees,$absent,[$organizer,$secretary])));if($actor&&!OrgAccess::canAssignScope($actor,$targets))throw new DomainException('انتخاب کاربر خارج از محدوده سازمانی شما مجاز نیست.');return ['title'=>$title,'meeting_type'=>self::text($d['meeting_type']??'general',50)?:'general','meeting_date'=>$date,'start_time'=>$start,'end_time'=>$end,'location'=>self::text($d['location']??'',255)?:null,'organizer_user_id'=>$organizer,'secretary_user_id'=>$secretary,'attendees'=>$attendees,'absent_users'=>$absent,'agenda'=>self::text($d['agenda']??'',10000),'meeting_summary'=>self::text($d['meeting_summary']??'',30000),'attachments'=>is_array($d['attachments']??null)?$d['attachments']:[]];}
 private static function decisionData(array $d):array{$type=in_array($d['decision_type']??'',array_keys(self::DECISION_TYPES),true)?$d['decision_type']:'decision';$responsible=(int)($d['responsible_user_id']??0)?:null;$supervisor=(int)($d['supervisor_user_id']??0)?:null;$due=trim((string)($d['due_date']??''));if(in_array($type,['action','followup','reminder'],true)&&!$responsible)throw new InvalidArgumentException('لطفاً مسئول پیگیری را انتخاب کنید.');if(in_array($type,['action','followup','reminder'],true)&&$due==='')throw new InvalidArgumentException('تاریخ مهلت انجام معتبر نیست.');$actor=Auth::user();if($actor&&!OrgAccess::canAssignScope($actor,array_values(array_filter([$responsible,$supervisor]))))throw new DomainException('ارجاع مصوبه خارج از محدوده سازمانی شما مجاز نیست.');return ['title'=>self::required($d['title']??'','عنوان مصوبه'),'description'=>self::text($d['description']??'',30000),'decision_type'=>$type,'category'=>self::text($d['category']??'',100)?:null,'responsible_user_id'=>$responsible,'responsible_unit_id'=>(int)($d['responsible_unit_id']??0)?:null,'supervisor_user_id'=>$supervisor,'priority'=>in_array($d['priority']??'',array_keys(self::PRIORITIES),true)?$d['priority']:'normal','due_date'=>$due!==''?self::date($due):null,'followup_status'=>self::status($d['followup_status']??'not_started'),'progress_percent'=>max(0,min(100,(int)($d['progress_percent']??0))),'latest_followup_note'=>self::text($d['latest_followup_note']??'',5000),'is_rule'=>!empty($d['is_rule'])?1:0,'rule_effective_date'=>trim((string)($d['rule_effective_date']??''))?self::date($d['rule_effective_date']):null,'rule_expire_date'=>trim((string)($d['rule_expire_date']??''))?self::date($d['rule_expire_date']):null];}
 private static function status(string $s):string{if(!array_key_exists($s,self::DECISION_STATUSES))throw new InvalidArgumentException('وضعیت پیگیری معتبر نیست.');return $s;}private static function date(mixed $v):string{$v=trim((string)$v);if(str_contains($v,'/'))$v=JalaliDate::toGregorian($v)??'';$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new InvalidArgumentException('تاریخ معتبر نیست.');return $v;}private static function time(mixed $v):?string{$v=trim((string)$v);if($v==='')return null;if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$v))throw new InvalidArgumentException('ساعت معتبر نیست.');return $v.':00';}
 private static function required(mixed $v,string $label):string{$v=self::text($v,255);if($v==='')throw new InvalidArgumentException("لطفاً {$label} را وارد کنید.");return $v;}private static function text(mixed $v,int $n):string{$v=trim(strip_tags((string)$v));return function_exists('mb_substr')?mb_substr($v,0,$n,'UTF-8'):substr($v,0,$n);}private static function encode(array $v):string{return json_encode(array_values($v),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'[]';}private static function json(?string $v):array{$x=json_decode((string)$v,true);return is_array($x)?$x:[];}private static function jsonIds(?string $v):array{return array_values(array_filter(array_map('intval',self::json($v))));}
